-- Burnflakes budget: seed data generated from 'תקציב ברנפלקס 2025.xlsx'
begin;



 select id, v, l, s from scenario_parameters p, (values
   ('shade_type','net','רשת צל + הקמה',1), ('shade_type','sail','מפרשי צל',2), ('shade_type','none','ללא הצללה מרכזית',3),
   ('gift_level','basic','בסיסי',1), ('gift_level','standard','רגיל (כמו 2025)',2), ('gift_level','premium','מושקע',3)
 ) o(k,v,l,s) where p.key = o.k;

-- cost item catalog = every line of the 2025 initial estimate

-- gift level: overrides on the cornflakes/milk unit cost
 select ci.id, 'gift_level', o.v, ci.unit_cost * o.m from cost_items ci
 join departments d on d.id = ci.department_id and d.slug = 'gift'
 cross join (values ('basic', 0.6), ('premium', 1.6)) o(v, m)
 where ci.name_he in ('קורנפלקסים', 'חלב');
-- shade type: the net line only applies when shade_type = net
update cost_items set applies_when = '{"shade_type": "net"}' where name_he like 'רשת צל%';


 select '00000000-0000-0000-0000-00000000a025', id,
   case key when 'member_count' then '35' when 'buffer_pct' then '0' else default_value end
 from scenario_parameters;

-- actual 2025 department lines -> staging table (the sheet has no payer key, so they are reconciled to expenses by hand later)
create table if not exists legacy_2025_department_actuals (id serial primary key, department_slug text, name_he text, amount numeric(12,2), paid_by_text text, matched_expense_id uuid);


-- members (from the container sheet) + 2025 membership with tier

-- funds of 2025

-- container fund payments (2025)

-- camp dues payments + participation share (2025)
update event_members set participation_share = round(1100.0/1350, 4) where id = (select em.id from event_members em join members m on m.id=em.member_id where m.first_name='עינת' and m.last_name='בן שושן' and em.event_id='00000000-0000-0000-0000-000000002025');
-- members without a camp-dues payment in 2025 were not attending (container fund only)
update event_members em set attending = false where em.event_id='00000000-0000-0000-0000-000000002025' and not exists (select 1 from payments p where p.event_member_id = em.id and p.fund_id='00000000-0000-0000-0000-00000000f001');

commit;